import type { Opportunity } from './opportunity-model';

export const TimePeriodPeriodTypeKeyToLabel = {
  'Weekly': 'Weekly',
  'Monthly': 'Monthly'
} as const;
export type TimePeriodPeriodTypeKey = keyof typeof TimePeriodPeriodTypeKeyToLabel;

export const TimePeriodStatusKeyToLabel = {
  'Open': 'Open',
  'Closed': 'Closed',
  'Locked': 'Locked'
} as const;
export type TimePeriodStatusKey = keyof typeof TimePeriodStatusKeyToLabel;

export interface TimePeriod {
  /**
   * @displayName Time Period
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Time Period Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  timePeriodName: string;
  /**
   * @displayName End Date
   * @validationRule Required for create/update operations
   */
  endDate: string;
  /**
   * @displayName Fiscal Year
   * @validationRule Required for create/update operations
   */
  fiscalYear: number;
  /**
   * @displayName Opportunity
   */
  opportunity?: Pick<Opportunity, 'id' | 'opportunityID'>;
  /**
   * @displayName Period Number
   * @validationRule Required for create/update operations
   */
  periodNumber: number;
  /**
   * @displayName Period Type
   * @validationRule Required for create/update operations
   */
  periodTypeKey: TimePeriodPeriodTypeKey;
  /**
   * @displayName Start Date
   * @validationRule Required for create/update operations
   */
  startDate: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: TimePeriodStatusKey;
}

export const _TimePeriod = 'TimePeriod' as const;